function guarded(fn){const run=()=>{try{return fn()}catch(e){render();toast(e instanceof SaveError?e.message:'Could not complete that action: '+e.message);return false}};if(typeof navigator!=='undefined'&&navigator.locks?.request)return navigator.locks.request(KEY+'-write',run);if(typeof indexedDB!=='undefined')return coordinationLock(run).catch(()=>{toast('Browser storage is unavailable. Changes were not applied.');return false});return run()}

let coordinationDatabase;
function coordinationLock(run){if(!coordinationDatabase)coordinationDatabase=new Promise((resolve,reject)=>{const request=indexedDB.open('strength-coach-coordination',1);request.onupgradeneeded=()=>request.result.createObjectStore('locks');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});return coordinationDatabase.then(db=>new Promise((resolve,reject)=>{const tx=db.transaction('locks','readwrite');let result;const store=tx.objectStore('locks'),r=store.get('write');r.onsuccess=()=>{result=run();store.put(Date.now(),'write')};tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)}))}
