function formatTargets(e,sets){if(!sets.length)return 'No sets planned';const reps=sets.map(x=>x.reps);const repText=new Set(reps).size===1?reps[0]:reps.join(' / ');if(e.timed)return sets.length+' sets · '+repText+' sec';if(!loaded(e))return sets.length+' sets · '+repText+' reps · '+(e.gear.includes('bands')?'Band resistance':'Bodyweight');const weights=sets.map(x=>x.weight),same=new Set(weights).size===1;return sets.length+' sets · '+repText+' reps · '+(same?(weights[0]>0?toDisplay(weights[0])+' '+state.profile.units+(e.unit==='each'?' each':''):'Choose starting load'):'Loads per set')}

function coaching(){const p=displayedPlan(),id=p.items[0]?.id;if(!id)return {text:'This equipment needs a different workout.',title:'Equipment coverage',explanation:'No supported session fits the selected equipment. Preview different equipment before starting.'};const r=recentEntry(id);if(r&&!r.sample)return {text:'Your last '+DB[id].name.toLowerCase()+' sets are ready to review.',title:'Your recorded performance',explanation:'Targets reuse the last recorded values for this exercise. This prototype does not generate a live AI progression prescription.'};return {text:id==='floor'?'Keep the weight. Aim for one more rep on your floor press.':'Your next session uses familiar movements and supported equipment.',title:'Based on sample history',explanation:id==='floor'?'The sample floor press was 15 kg per dumbbell for 9, 9, and 8 reps. The illustrative target is 9, 9, and 9 at the same weight. Edit it to match your actual set.':'Exercise variants retain separate histories. Choose a starting load when no comparable record exists.'}}

