function savingNotice(){return storageError?'<div class="save-warning">Changes are not saved on this device. <button class="text-btn" data-action="retry-save">Retry saving</button></div>':''}
function nav(){const hidden=['workout','adapt','recap','review-plan'].includes(route);$('#nav').hidden=hidden;$('#nav').innerHTML=['today','plan','progress','coach'].map((r,i)=>`<a href="#${r}" class="${route===r?'active':''}" ${route===r?'aria-current="page"':''}>${icon(['home','plan','progress','coach'][i])}<span>${['Today','Plan','Progress','Coach'][i]}</span></a>`).join('')}
function today(){const p=state.profile,active=state.session,d=displayedPlan(),rows=d.items,first=rows[0]&&DB[rows[0].id],done=weekHistory().length,coach=coaching(),pres=first?prescribed(first.id,rows[0].sets):null;return `<div class="between"><div><p class="greeting">Good morning,</p><h1 class="greeting-name">${esc(p.name)}.</h1></div><button class="avatar" data-action="profile" aria-label="Open profile and settings">${esc(p.name.slice(0,1).toUpperCase())}</button></div><div class="weekly"><span>${done} of ${p.days} sessions this week</span><div class="week-dots">${Array.from({length:p.days},(_,i)=>`<i class="${i<done?'done':''}"></i>`).join('')}</div></div>${savingNotice()}${active?`<div class="notice mb16"><div class="between"><span>Session in progress · ${actualCount(active)} sets logged</span><button class="text-btn" data-action="resume">Resume ${icon('arrow')}</button></div></div>`:''}<div class="hero"><div class="hero-image"></div><div class="hero-copy"><span class="small muted">${state.draft?'Your approved version':'Your next workout'}</span><h2>${esc(d.name)}</h2><p>${d.minutes} min estimated · ${esc(d.location)}</p></div></div>${d.warnings.map(w=>`<div class="notice amber mt16">${esc(w)}</div>`).join('')}<div class="coach-inline"><span class="coach-ring"></span><div><div class="eyebrow">Your coach · prototype</div><p>${esc(coach.text)}</p><div class="coach-actions"><button class="text-btn" data-action="adjust">${icon('tune')} Adjust today</button><button class="text-btn muted" data-action="why">Why this target ${icon('arrow')}</button></div></div></div><div class="section-title"><h3>Your workout</h3><button data-action="library">View all ${rows.length} ${icon('arrow')}</button></div>${first?`<div class="exercise-card"><button class="exercise-head" data-action="exercise" data-id="${first.id}">${thumb(first)}<span class="detail"><h4>${esc(first.name)}</h4><p>${target(first,rows[0].sets)}</p></span></button><div class="comparison"><div><label>${!recentEntry(first.id)?'Example baseline':recentEntry(first.id).sample?'Last sample session':'Last recorded session'}</label><strong>${pres.previous.length?pres.previous.slice(0,rows[0].sets).join(' · '):'—'}</strong></div><div><label>Today’s target</label><strong>${pres.sets.map(x=>x.reps).join(' · ')}</strong></div></div><small class="muted">${!recentEntry(first.id)||recentEntry(first.id).sample?'Illustrative history':'Recorded values'} · reps per set${loaded(first)?' · review working loads':''}</small></div>${rows.slice(1,3).map(x=>exerciseRow(x.id,x.sets)).join('')}${rows.length>3?'<p class="small muted mt8">+ '+(rows.length-3)+' more in View all</p>':''}`:'<div class="notice amber">No supported workout with this setup. Choose different equipment.</div>'}<button class="primary home-start" data-action="start" ${!rows.length&&!active?'disabled':''}>${active?'Resume workout':'Start workout'} ${icon('arrow')}</button>`}
function plan(){const done=weekHistory().filter(h=>!h.sample),start=weekStart(),today=new Date();return `<div class="subpage-head"><div><span class="eyebrow">A FAMILIAR PLAN</span><h2 class="mt8">Room for real life.</h2><p>${state.profile.days} sessions · ${durationAt()} minutes · ${esc(state.profile.location)}</p></div><button class="icon-btn" data-action="plan-settings" aria-label="Edit plan settings">${icon('tune')}</button></div><div class="segmented"><button data-action="plan-tab" data-tab="week" class="${planTab==='week'?'active':''}">Your week</button><button data-action="plan-tab" data-tab="equipment" class="${planTab==='equipment'?'active':''}">Equipment</button></div>${planTab==='equipment'?equipmentView():`<div class="plan-week">${['M','T','W','T','F','S','S'].map((name,i)=>{const date=new Date(start);date.setDate(start.getDate()+i);return `<button class="day ${date.toDateString()===today.toDateString()?'selected':''}" data-action="day" data-i="${i}" aria-label="View ${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]}"><span>${name}</span><strong>${date.getDate()}</strong><small></small></button>`}).join('')}</div><div class="notice">Train in sequence. A missed day doesn’t erase your progress or add catch-up work.</div>${state.scheduledTrial?`<div class="notice mt16">25-minute trial scheduled for ${new Date(state.scheduledTrial.startAt).toLocaleDateString('en-US',{month:'short',day:'numeric'})}. <button class="text-btn" data-action="preview-week">Review</button></div>`:''}${Array.from({length:Math.max(state.profile.days,done.length)},(_,i)=>{const h=done[i],seq=state.sequence+Math.max(0,i-done.length),p=resolvedPlan(seq);return `<div class="plan-session"><div class="between"><div class="row"><span class="number">${String(i+1).padStart(2,'0')}</span><div><span class="eyebrow">${h?'COMPLETED'+(h.sample?' · SAMPLE':''):i===done.length?'UP NEXT':'PLANNED'}</span><h4>${esc(h?.name||p.name)}</h4><div class="meta">${h?h.minutes+' min · '+h.setCount+' '+(h.setCount===1?'set':'sets'):p.minutes+' min · '+p.items.length+' exercises'}</div></div></div>${h?icon('check'):''}</div><div class="between mt8"><span class="small muted">${h?h.partial?'Finished early':'Work recorded':p.warnings.length?'Equipment limitations noted':'Your selected equipment'}</span><button class="text-btn" data-action="${h?'history':'preview-plan'}" ${h?'data-id="'+esc(h.id)+'"':'data-index="'+seq+'"'}>${h?'View record':'View session'} ${icon('arrow')}</button></div></div>`}).join('')}<button class="secondary mt24" data-action="plan-settings">Edit weekly preferences</button>`}`}
function equipmentView(){return `<div class="card"><div class="between"><h3>${esc(state.profile.location)}</h3><button class="text-btn" data-action="equipment">Edit</button></div><p>${state.profile.gear.map(x=>({dumbbells:'Adjustable dumbbells',bodyweight:'Floor space',bands:'Resistance bands',barbell:'Barbell',bench:'Bench',kettlebell:'Kettlebell'})[x]).join(' · ')||'No equipment selected'}</p></div><div class="notice mt16">Only supported exercises appear in your workout. Equipment changes are previewed before applying.</div><h3 class="mt24">Available exercises</h3>${Object.values(DB).filter(e=>available(e.id)).map(e=>exerciseRow(e.id)).join('')}<button class="secondary mt24" data-action="equipment">Change equipment</button>`}
function progress(){const h=state.history,real=h.filter(x=>!x.sample),totalSets=h.reduce((n,x)=>n+x.setCount,0);return `<div class="subpage-head"><div><span class="eyebrow">THE WORK YOU PUT IN</span><h2 class="mt8">Your progress.</h2><p>Small steps, clearly recorded.</p></div><button class="icon-btn" data-action="export" aria-label="Export workout history">${icon('download')}</button></div><div class="notice small">${real.length?`${real.length} session${real.length!==1?'s':''} logged in this prototype. Earlier records are sample data.`:'Sample history is shown below. Finish a workout to add your own session.'}</div><div class="segmented"><button data-action="progress-tab" data-tab="overview" class="${progressTab==='overview'?'active':''}">Overview</button><button data-action="progress-tab" data-tab="history" class="${progressTab==='history'?'active':''}">History</button></div>${progressTab==='overview'?`<div class="stat-grid"><div class="stat"><strong>${h.length}</strong><span>Sessions</span></div><div class="stat"><strong>${totalSets}</strong><span>Working sets</span></div><div class="stat"><strong>${h.reduce((n,x)=>n+x.minutes,0)}</strong><span>Minutes logged</span></div></div><div class="card"><div class="between"><h4>Recorded reps</h4><select class="chart-switch" id="progress-exercise" aria-label="Select exercise for progress">${['floor','squat','row'].map(id=>`<option value="${id}" ${selectedProgress===id?'selected':''}>${DB[id].name}</option>`).join('')}</select></div><p>Actual recorded sets · ${DB[selectedProgress].name}</p><div class="chart">${state.history.filter(h=>h.entries.some(e=>e.id===selectedProgress)).slice(0,5).reverse().map(h=>{const e=h.entries.find(e=>e.id===selectedProgress),sets=historySets(e),n=sets.reduce((sum,x)=>sum+x.reps,0);return `<div class="bar-col"><strong>${n}</strong><div class="bar" style="height:${Math.max(5,Math.min(85,n*2))}px;opacity:${h.sample?.55:1}"></div><span>${new Date(h.date).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span></div>`}).join('')||'<p class="no-data">No records for this exercise yet.</p>'}</div><p class="small">Reps per session. Open a record to compare individual loads; more total reps alone does not measure strength.</p></div><div class="section-title"><h3>Recent sessions</h3><button data-action="all-history">View all</button></div>${h.slice(0,3).map(historyRow).join('')}`:h.map(historyRow).join('')}`}
function historyRow(h){const d=new Date(h.date);return `<button class="history-row" data-action="history" data-id="${esc(h.id)}"><span class="history-date">${d.toLocaleDateString('en-US',{month:'short'})}<strong>${d.getDate()}</strong></span><span class="detail"><h4>${esc(h.name)}</h4><p>${h.minutes} min · ${h.setCount} ${h.setCount===1?'set':'sets'}${h.sample?' · Sample':''}${h.partial?' · Finished early':''}</p></span>${icon('chevron')}</button>`}
function coach(){return `<div class="subpage-head"><div><span class="eyebrow">YOUR COACH · GUIDED DEMO</span><h2 class="mt8">A plan that<br>learns you.</h2><p>You decide what changes.</p></div><span class="coach-ring"></span></div><div class="segmented"><button data-action="coach-tab" data-tab="review" class="${coachTab==='review'?'active':''}">Weekly review</button><button data-action="coach-tab" data-tab="memory" class="${coachTab==='memory'?'active':''}">Memory</button><button data-action="coach-tab" data-tab="chat" class="${coachTab==='chat'?'active':''}">Ask coach</button></div>${coachTab==='memory'?memoryView():coachTab==='chat'?chatView():reviewView()}`}
function memoryView(){return `<p class="sleeping mb16">Equipment and session preferences are linked to training settings. Custom notes are saved for review. Temporary changes apply to one session.</p>${state.memories.map(m=>`<div class="memory-row">${icon(m.icon)}<div class="detail"><strong>${esc(m.label)}</strong><p>${esc(m.value)}</p><span class="pill mt8">Confirmed</span></div><button class="icon-btn" data-action="edit-memory" data-id="${esc(m.id)}" aria-label="Edit ${esc(m.label)}">${icon('edit')}</button></div>`).join('')}${state.draft?'<div class="memory-row">'+icon('clock')+'<div class="detail"><strong>Today’s adjustment</strong><p>'+state.draft.minutes+' minutes · '+esc(state.draft.location)+'</p><span class="pill amber mt8">This session only</span></div></div>':''}<button class="secondary mt24" data-action="add-memory">${icon('plus')} Add a preference</button>`}
function reviewView(){return `<div class="card"><span class="eyebrow">A PATTERN TO CHECK · RECORDED DURATIONS</span><h3 class="insight-title">Shorter sessions may fit better.</h3><p>${state.history.slice(0,5).filter(h=>h.minutes<30).length} of your last ${Math.min(5,state.history.length)} recorded sessions were under 30 minutes.</p><div class="chart">${state.history.slice(0,5).reverse().map(h=>h.minutes).map(n=>`<div class="bar-col"><strong>${n}</strong><div class="bar" style="height:${Math.max(4,Math.min(85,n*2))}px;background:${n<30?'#bdef83':'#4a5840'}"></div><span>min</span></div>`).join('')}</div><div class="divider"></div><h4>${state.scheduledTrial?'Your shorter-week trial is scheduled.':'Try 25-minute sessions next week?'}</h4><div class="check-line">${icon('check')} Keep ${state.profile.days} sessions</div><div class="check-line">${icon('check')} Keep familiar core movements</div><div class="check-line">${icon('check')} Reduce optional work</div><button class="primary mt16" data-action="preview-week">${state.scheduledTrial?'Review scheduled trial':'Preview next week'} ${icon('arrow')}</button><button class="text-btn muted" style="width:100%;justify-content:center" data-action="keep-plan">Keep current plan</button><p class="small center">Nothing changes until you approve.</p></div><div class="section-title"><h3>What I remember</h3><button data-action="show-memory">Edit memories</button></div>${state.memories.slice(0,2).map(m=>`<div class="memory-row">${icon(m.icon)}<div class="detail"><strong>${esc(m.value)}</strong></div><span class="pill">Confirmed</span></div>`).join('')}<button class="secondary mt24" data-action="show-chat">Talk through a change ${icon('coach')}</button>`}
function chatView(){return `<div class="chat-thread">${state.chat.map(m=>`<div class="message ${m.role}">${esc(m.text)}</div>`).join('')}</div><div class="chips mb16"><button class="chip" data-action="chat-prompt" data-text="I only have 20 minutes today">20 minutes today</button><button class="chip" data-action="chat-prompt" data-text="I have no equipment today">No equipment</button><button class="chip" data-action="chat-prompt" data-text="Why this target?">Why this target?</button></div><form id="chat-form" class="chat-compose"><input id="chat-input" placeholder="What would make today easier?" aria-label="Message your demo coach" maxlength="350" autocomplete="off"><button aria-label="Send message">${icon('arrow')}</button></form><p class="small muted mt16">Guided prototype responses. No AI service or medical assessment is connected.</p>`}
function adjustment(){if(!draftPreview){draftPreview=buildAdjustment(20,state.profile.gear,state.profile.location)}let d=draftPreview;return `<div class="back-head"><button class="icon-btn" data-action="back-adjust" aria-label="Back">${icon('back')}</button><div><h3>Make today fit.</h3><p class="small muted">${d.scope==='program'?'Equipment settings':state.session?'Adjust remaining work':d.name}</p></div></div>${savingNotice()}<div class="message user" style="max-width:100%">${esc(d.request||d.minutes+' minutes · '+d.location)}</div><div class="adapt-metric"><span>${state.session?state.session.minutes:state.profile.duration}</span><span class="arrow">→</span><span>${d.minutes}</span></div><div class="between mb16"><span class="eyebrow">MINUTES, ESTIMATED</span><span class="pill amber">${d.scope==='program'?'PROGRAM SETTINGS':'TODAY ONLY'}</span></div><h3>Review your changes.</h3>${d.warnings.map(w=>`<div class="notice amber mt16">${esc(w)}</div>`).join('')}${d.items.map(x=>{const e=DB[x.id];return exerciseRow(x.id,x.sets,'exercise',`<span class="delta">${x.original===x.sets?'Keep':x.original+' → '+x.sets+' sets'}</span>`) }).join('')}${d.removed.length?`<div class="notice amber mt16">${d.removed.map(id=>DB[id].name).join(', ')} removed from unfinished work.</div>`:''}<div class="adjust-preserve">${icon('lock')} ${d.scope==='program'?'Applies to future workouts. Active session unchanged.':state.session?'Completed sets stay saved.':'Your original program stays saved.'}</div><p class="small muted">Less total work. Estimate includes rest and setup; actual time may vary. New movements need a starting point.</p><button class="text-btn mt8" data-action="adjust-controls">${icon('tune')} Edit this version</button><button class="primary mt16" data-action="apply-adjust" ${!d.items.length?'disabled':''}>Use this version ${icon('arrow')}</button><button class="secondary mt8" data-action="cancel-adjust">Keep original</button>`}
function buildAdjustment(minutes,gear,location,request,scope='today'){const s=scope==='program'?null:state.session;const base=s?s.items.filter(x=>x.sets.some(y=>!y.done)).map(x=>x.exerciseId):planIdsAt();const ids=[],sources={},warnings=[],removed=[];for(const id of base){if(available(id,gear)&&!ids.includes(id)){ids.push(id);sources[id]=s?.items.find(x=>x.exerciseId===id)?.sourceId||id;}else{const replacement=replacementFor(id,gear,ids);if(replacement){ids.push(replacement.id);sources[replacement.id]=s?.items.find(x=>x.exerciseId===id)?.sourceId||id;}else{removed.push(id);warnings.push('No supported '+DB[id].pattern+' movement with this equipment.')}}}let kept=minutes<=30?ids.slice(0,3):ids;removed.push(...ids.filter(id=>!kept.includes(id)));const n=minutes<=25?2:3;const items=kept.map(id=>{const old=s?.items.find(x=>x.exerciseId===id),remaining=old?old.sets.filter(y=>!y.done).length:DB[id].sets;return {id,sourceId:sources[id],sets:Math.min(n,remaining),original:remaining}}).filter(x=>x.sets>0);if(!items.length)warnings.splice(0,warnings.length,gear.includes('kettlebell')?'Kettlebell-only sessions are not supported. Choose another setup.':'No supported workout fits this equipment. Choose another setup.');return {minutes,gear:[...gear],location,scope,sequence:state.sequence,name:'Full body '+(state.sequence%2?'B':'A'),items,removed:[...new Set(removed)],warnings,request:request||`${minutes} minutes · ${location}`}}
function activeWorkout(){let s=state.session;if(!s)return `<div class="empty"><h3>No session in progress.</h3><p class="mt16">Start a workout from Today.</p><button class="primary mt24" data-action="go-today">Go to Today</button></div>`;let idx=s.currentIndex||0;if(idx>=s.items.length)idx=0;let item=s.items[idx],e=DB[item.exerciseId],done=actualCount(s),total=totalCount(s),next=item.sets.findIndex(x=>!x.done);let elapsed=((s.pausedAt||Date.now())-s.startedAt-(s.pauseMs||0))/1000;return `<div class="between"><button class="icon-btn" data-action="minimize" aria-label="Minimize workout">${icon('back')}</button><h4>${esc(s.name)}</h4><button class="text-btn" data-action="finish-sheet">Finish</button></div><div class="workout-status"><span>${icon('clock')} <span id="elapsed">${fmtTime(elapsed)}</span>${s.pausedAt?' · Paused':''}</span><span class="saved-note">${storageError?'Unsaved changes':'✓ Saved on this device'}</span></div>${savingNotice()}<div class="between"><span class="small muted">${done} of ${total} sets logged</span><button class="text-btn small" data-action="pause-session">${s.pausedAt?'Resume':'Pause'}</button></div><div class="segments">${Array.from({length:total},(_,i)=>`<i class="${i<done?'done':''}"></i>`).join('')}</div><h2 class="workout-title">${esc(e.name)}</h2><p class="small muted">Exercise ${idx+1} of ${s.items.length}${e.unit==='each'?' · Weight per dumbbell':''}</p><button class="technique-panel" data-action="technique" data-id="${e.id}"><span class="icon-btn">${icon('info')}</span><span><strong>Setup & technique</strong><small>View the exercise guide</small></span>${icon('chevron')}</button><div class="set-head"><span>SET</span><span>PREVIOUS</span><span>${loaded(e)?state.profile.units.toUpperCase():'LOAD'}</span><span>${e.timed?'SEC':'REPS'}</span><span></span></div>${item.sets.map((set,i)=>`<div class="set-row ${set.done?'complete':i===next?'current':''}"><span>${i+1}</span><span>${item.previous[i]!==undefined?(loaded(e)?toDisplay(item.previousLoads?.[i]??e.weight)+' × ':'')+item.previous[i]:'—'}</span>${loaded(e)?`<input type="number" step="any" min="0" max="${state.profile.units==='kg'?1000:toDisplay(1000)}" value="${set.weight===0?'':toDisplay(set.weight)}" data-set-field="weight" data-set="${i}" aria-label="Set ${i+1} weight in ${state.profile.units}">`:`<span class="bodyweight-load">${e.gear.includes('bands')?'Band':'BW'}</span>`}<input type="number" min="1" max="999" value="${set.reps}" data-set-field="reps" data-set="${i}" aria-label="Set ${i+1} ${e.timed?'seconds':'reps'}"><button data-action="toggle-set" data-index="${i}" aria-label="${set.done?'Undo logged':'Log'} set ${i+1}">${set.done?icon('check'):'○'}</button></div>`).join('')}<div class="rest"><div class="detail"><span class="eyebrow">REST</span><div class="rest-num" id="rest-time">${s.restUntil?fmtTime((s.restUntil-(s.pausedAt||Date.now()))/1000):'1:30'}</div></div><button data-action="add-rest">+30 sec</button><button data-action="skip-rest">Skip</button></div><div class="row small muted">${icon('coach')} ${item.previous.length?'Review the suggested values against your last recorded sets.':'Choose your own starting point; no comparable history yet.'}</div><p class="small muted mt8">Suggested values. Edit to match your actual set.</p>${(s.warnings||[]).map(w=>'<div class="notice amber mt16">'+esc(w)+'</div>').join('')}${s.pausedAt?'<div class="notice mt16">Workout paused. Resume before logging another set.</div>':''}<div class="session-footer"><button class="primary" data-action="log-next" ${s.pausedAt?'disabled':''}>${icon('check')} ${next<0?(idx<s.items.length-1?'Next exercise':'Review workout'):'Log set '+(next+1)}</button><div class="session-actions"><button data-action="swap" data-index="${idx}">${icon('swap')} Swap exercise</button><button data-action="adjust">${icon('tune')} Adjust remaining</button></div></div>${idx<s.items.length-1?`<button class="exercise-row next-up" data-action="next-exercise"><span class="eyebrow">NEXT</span>${thumb(DB[s.items[idx+1].exerciseId])}<span class="detail"><strong>${DB[s.items[idx+1].exerciseId].name}</strong><p>${s.items[idx+1].sets.length} sets</p></span>${icon('chevron')}</button>`:''}<button class="text-btn muted mt8" data-action="session-outline">View all exercises</button>`}
function recap(){let h=state.history.find(x=>x.id===state.lastFinished);if(!h)return '<div class="empty">No completed session yet.<button class="primary mt16" data-action="go-today">Go to Today</button></div>';return `<div class="center"><div class="success-ring">${icon('check')}</div><span class="eyebrow">WORK RECORDED</span><h2 class="mt8">You showed up.</h2><p class="muted mt8">${esc(h.name)}${h.partial?' · Finished early':''}</p></div><div class="stat-grid"><div class="stat"><strong>${h.minutes}</strong><span>Minutes</span></div><div class="stat"><strong>${h.setCount}</strong><span>Sets logged</span></div><div class="stat"><strong>${h.entries.length}</strong><span>Exercises</span></div></div><div class="card"><h3>How did today fit?</h3><p>Save feedback for your review. This prototype does not automatically change prescriptions from feedback.</p><div class="feedback-options">${['Too much','About right','Too little'].map(t=>`<button class="${state.feedback[h.id]===t?'selected':''}" data-action="feedback" data-value="${t}">${t}</button>`).join('')}</div></div><div class="notice mt16">${h.partial?'Only completed sets were recorded. There is no automatic catch-up work.':'Your completed sets are saved in this browser. You can review or correct them in History.'}</div><button class="primary mt24" data-action="go-progress">View workout history ${icon('arrow')}</button><button class="secondary mt8" data-action="go-today">Back to Today</button>`}
function reviewPlan(){const start=state.scheduledTrial?new Date(state.scheduledTrial.startAt):nextWeekStart();return `<div class="back-head"><button class="icon-btn" data-action="go-coach" aria-label="Back to coach">${icon('back')}</button><h3>Preview next week</h3></div><h2>A shorter week.<br>Same familiar lifts.</h2><p class="muted mt16">Starts ${start.toLocaleDateString('en-US',{month:'long',day:'numeric'})} · ${state.profile.days} sessions · 25 minutes</p><div class="notice mt24">A one-week trial. Today’s workout and completed records stay unchanged. Your regular duration returns after the trial.</div>${Array.from({length:state.profile.days},(_,i)=>{const p=resolvedPlan(state.sequence+i,state.profile.gear,25);return `<div class="trial-day"><span class="eyebrow">SESSION ${i+1}</span><h4 class="mt8">${p.name}</h4><p class="small muted mt8">${p.items.map(x=>DB[x.id].name).join(' · ')||'No supported session'}</p>${p.warnings.map(w=>`<p class="small muted">${esc(w)}</p>`).join('')}<span class="pill mt8">2 working sets per movement</span></div>`}).join('')}<button class="primary mt24" data-action="apply-week">${state.scheduledTrial?'Keep scheduled trial':'Schedule this trial'} ${icon('arrow')}</button><button class="secondary mt8" data-action="${state.scheduledTrial?'cancel-week':'go-coach'}">${state.scheduledTrial?'Cancel scheduled trial':'Keep current plan'}</button>`}
function render(){clearInterval(timerId);nav();const pages={today,plan,progress,coach,adapt:adjustment,workout:activeWorkout,recap,'review-plan':reviewPlan};$('#app').innerHTML=(pages[route]||today)();if(route==='workout')timerId=setInterval(tick,1000);document.title=(route==='today'?'Your Strength Coach':route[0].toUpperCase()+route.slice(1)+' · Your Strength Coach')}
function tick(){const s=state.session;if(!s)return;const now=s.pausedAt||Date.now(),elapsed=$('#elapsed');if(elapsed)elapsed.textContent=fmtTime((now-s.startedAt-(s.pauseMs||0))/1000);const rest=$('#rest-time');if(rest&&s.restUntil){const left=(s.restUntil-now)/1000;rest.textContent=left>0?fmtTime(left):'Ready'}}
function sheet(title,body){lastFocus=document.activeElement;$('#overlay').hidden=false;$('#overlay').innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-grip"></div><div class="sheet-head"><h3>${title}</h3><button class="icon-btn" data-action="close-sheet" aria-label="Close dialog">${icon('close')}</button></div>${body}</section>`;document.body.style.overflow='hidden';setTimeout(()=>$('#overlay').querySelector('input,select,textarea,button')?.focus(),30)}
function closeSheet(){const open=!$('#overlay').hidden;$('#overlay').hidden=true;$('#overlay').innerHTML='';document.body.style.overflow='';if(open)lastFocus?.focus?.()}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSheet();if(e.key==='Tab'&&!$('#overlay').hidden){const els=[...$('#overlay').querySelectorAll('button,input,select,textarea,a')].filter(x=>!x.disabled);if(!els.length)return;if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))closeSheet()});
function technique(id){let e=DB[id];sheet(e.name,`<span class="pill">${e.equipment}</span><div class="technique-label mt16">${icon('dumbbell')} ${esc(e.equipment)} · Text guide</div><ol class="technique-steps">${e.cues.map(x=>`<li>${x}</li>`).join('')}</ol><p class="small muted">Illustrative technique guide. No form assessment or video service is connected.</p><button class="secondary" data-action="close-sheet">Back to workout</button>`)}
function exercise(id){let e=DB[id],active=state.session?.items.find(x=>x.exerciseId===id),planned=displayedPlan().items.find(x=>x.id===id),count=active?.sets.length??planned?.sets??e.sets;sheet(e.name,`<div class="between"><span class="pill">${e.pattern[0].toUpperCase()+e.pattern.slice(1)}</span><span class="small muted">${e.gear.join(' + ')}</span></div><div class="technique-label mt16">${icon('dumbbell')} ${esc(e.equipment)} · Text guide</div><h3 class="mt16">${active?formatTargets(e,active.sets):target(e,count)}</h3><p class="small muted mt8">${recentEntry(id)?(recentEntry(id).sample?'Sample':'Recorded')+' previous reps: '+historySets(recentEntry(id).entry).map(x=>x.reps).join(' · '):'No comparable history. Choose your own starting point.'}</p><button class="secondary mt16" data-action="technique" data-id="${esc(id)}">${icon('play')} Technique guide</button><div class="divider"></div><p class="small muted">Exercise variants keep separate histories. Different movements do not inherit working weights automatically.</p>`)}
function settings(){sheet('Your settings',`<form id="profile-form"><div class="field"><label for="profile-name">Your first name</label><input id="profile-name" value="${esc(state.profile.name)}" maxlength="25" required></div><div class="field"><label for="profile-units">Display units</label><select id="profile-units"><option value="kg" ${state.profile.units==='kg'?'selected':''}>Kilograms (kg)</option><option value="lb" ${state.profile.units==='lb'?'selected':''}>Pounds (lb)</option></select></div><button class="primary">Save settings</button></form><div class="divider"></div><button class="settings-row" data-action="plan-settings">Training preferences ${icon('chevron')}</button><button class="settings-row" data-action="equipment">Equipment ${icon('chevron')}</button><button class="settings-row" data-action="export">Export demo data ${icon('download')}</button><button class="settings-row" data-action="restore">Restore an export ${icon('upload')}</button><button class="settings-row" data-action="reset">Reset sample data ${icon('undo')}</button><p class="small muted mt16">Interactive prototype. No account, live AI service, or health integration. Data stays in this browser; exporting gives you a portable copy.</p>`)}
function planSettings(){sheet('Training preferences',`<form id="plan-form"><div class="field"><label for="plan-goal">Goal</label><select id="plan-goal">${['Build strength consistently','Build muscle','Return to a routine'].map(x=>`<option ${state.profile.goal===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="plan-days">Sessions per week</label><select id="plan-days">${[2,3,4].map(n=>`<option value="${n}" ${state.profile.days===n?'selected':''}>${n} sessions</option>`).join('')}</select></div><div class="field"><label for="plan-duration">Preferred session length</label><select id="plan-duration">${[20,25,35,45].map(n=>`<option value="${n}" ${state.profile.duration===n?'selected':''}>${n} minutes</option>`).join('')}</select></div><div class="notice">Your session order stays intact. New preferences do not change completed sets or an active workout.</div><button class="primary">Save preferences</button></form>`)}
function equipmentSheet(){sheet('Your equipment',`<form id="equipment-form"><div class="field"><label for="equip-location">Location</label><select id="equip-location">${['Home','Gym','Hotel'].map(x=>`<option ${state.profile.location===x?'selected':''}>${x}</option>`).join('')}</select></div>${[['dumbbells','Adjustable dumbbells'],['bodyweight','Floor space / bodyweight'],['bands','Resistance bands'],['barbell','Barbell'],['bench','Bench'],['kettlebell','Kettlebell — not supported yet']].map(([id,label])=>`<label class="check-option"><input name="gear" type="checkbox" value="${id}" ${state.profile.gear.includes(id)?'checked':''}>${label}</label>`).join('')}<p class="small muted mt16">The preview checks every exercise’s equipment requirements. A missing movement pattern is shown honestly.</p><button class="primary">Preview equipment change</button></form>`)}
function controls(){const d=route==='adapt'&&draftPreview?draftPreview:(!state.session?state.draft:null),scope=d?.scope||'today';const gear=d?.gear||state.session?.gear||state.profile.gear;sheet(scope==='program'?'Edit equipment preview':'Adjust today',`<form id="adjust-form" data-scope="${scope}"><div class="field"><label for="adjust-mins">${scope==='program'?'Current duration — change in training preferences':'Time available'}</label><div class="range-row"><input id="adjust-mins" type="range" min="15" max="60" step="5" value="${scope==='program'?durationAt():d?.minutes||state.session?.minutes||durationAt()}" ${scope==='program'?'disabled':''}><output id="mins-output">${scope==='program'?durationAt():d?.minutes||state.session?.minutes||durationAt()} min</output></div></div><div class="field"><label for="adjust-location">Equipment for ${scope==='program'?'future workouts':'today'}</label><select id="adjust-location"><option value="preview">${d?'Keep preview equipment':'Current session equipment'}: ${esc(gear.join(', '))}</option><option value="dumbbells">Dumbbells and floor space</option><option value="bodyweight">Bodyweight only</option><option value="bands">Bands and floor space</option><option value="kettlebell">Kettlebell only (coverage check)</option></select></div><div class="notice">${scope==='program'?'Changes saved equipment settings for future workouts. Active session is unchanged.':state.session?'Only unfinished work changes. Completed sets stay saved.':'Today only. The ongoing program is kept.'}</div><button class="primary">Preview changes ${icon('arrow')}</button></form>`)}
function swap(index){const s=state.session;if(!s)return;const item=s.items[index],e=DB[item.exerciseId];if(!item.sets.some(x=>!x.done)){toast('All sets are already logged. No replacement needed.');return}const alternatives=Object.values(DB).filter(x=>x.id!==e.id&&x.pattern===e.pattern&&available(x.id,s.gear)&&!s.items.some(y=>y.exerciseId===x.id));sheet('Replace '+e.name,`<p class="small muted mb16">Same movement pattern; separate exercise history. Completed sets will stay recorded.</p>${alternatives.length?alternatives.map(x=>`<button class="exercise-row" data-action="apply-swap" data-id="${x.id}" data-index="${index}">${thumb(x)}<span class="detail"><strong>${esc(x.name)}</strong><p>${esc(x.equipment)}</p></span>${icon('chevron')}</button>`).join(''):'<div class="notice amber">No suitable replacement is available with your selected equipment. Keep this exercise, skip unfinished sets, or preview different equipment.</div>'}<button class="secondary mt16" data-action="skip-exercise" data-index="${index}">Skip unfinished sets</button><button class="text-btn" data-action="adjust">Preview different equipment</button>`)}
function outline(){const s=state.session;if(!s)return;sheet('Your session',s.items.map((x,i)=>`<button class="exercise-row" data-action="select-exercise" data-index="${i}">${thumb(DB[x.exerciseId])}<span class="detail"><strong>${esc(DB[x.exerciseId].name)}</strong><p>${x.sets.filter(s=>s.done).length} of ${x.sets.length} sets logged</p></span>${icon('chevron')}</button>`).join(''))}
function finishSheet(){const s=state.session;if(!s)return;const n=actualCount(s);sheet('Finish your session?',`<h3>${n} of ${totalCount(s)} sets logged.</h3><p class="muted mt16">${n?'Only completed sets enter your history. Unfinished work won’t become catch-up debt.':'No completed sets yet. Continue your workout or discard this empty session.'}</p>${n?'<button class="primary mt24" data-action="confirm-finish">Save completed work</button>':''}<button class="secondary mt8" data-action="close-sheet">Continue workout</button><button class="text-btn muted mt16" data-action="discard-session">Discard this session</button>`)}
function logNext(){const s=state.session;if(!s||s.pausedAt)return;const item=s.items[s.currentIndex],idx=item.sets.findIndex(x=>!x.done);if(idx<0){if(s.currentIndex<s.items.length-1){s.currentIndex++;persist();render()}else finishSheet();return}const set=item.sets[idx];if(loaded(DB[item.exerciseId])&&set.weight<=0){toast('Enter a starting load before logging this set.');return}set.done=true;set.completedAt=Date.now();s.restUntil=Date.now()+90000;persist();render();toast('Set '+(idx+1)+' logged')}
function finish(){if(saveBusy||!state.session)return;saveBusy=true;try{const s=state.session,done=actualCount(s);if(!done)return;const entries=s.items.filter(x=>x.sets.some(y=>y.done)).map(x=>summarizeEntry(x.exerciseId,x.sets.filter(y=>y.done)));if(!state.history.some(x=>x.id===s.id))state.history.unshift({id:s.id,name:s.name,date:new Date().toISOString(),minutes:Math.max(1,Math.round(((s.pausedAt||Date.now())-s.startedAt-(s.pauseMs||0))/60000)),setCount:done,entries,plannedSets:s.approvedTotal,originalPlannedSets:s.originalPlannedTotal,partial:done<s.approvedTotal||s.skippedCount>0,sample:false});state.lastFinished=s.id;state.session=null;state.draft=null;state.sequence++;persist();navigate('recap')}finally{saveBusy=false}}
function exportData(){const blob=new Blob([JSON.stringify({format:'strength-coach-export',version:1,exportedAt:new Date().toISOString(),data:state},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='strength-coach-export.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Export downloaded')}
function start(){if(state.session){navigate('workout');return}const d=displayedPlan();if(!d.items.length){toast('No supported session. Preview different equipment.');controls();return}state.session={id:uid(),name:d.name||'Full body '+(state.sequence%2?'B':'A'),planKey:state.sequence%2?'B':'A',startedAt:Date.now(),pauseMs:0,pausedAt:null,restUntil:null,minutes:d.minutes||durationAt(),gear:[...d.gear],location:d.location,currentIndex:0,warnings:[...(d.warnings||[])],items:d.items.map(x=>({...prescribed(x.id,x.sets),sourceId:x.sourceId||x.id})),skippedCount:0};state.session.approvedTotal=totalCount(state.session);state.session.originalPlannedTotal=state.session.approvedTotal;persist();navigate('workout')}
function applyAdjust(){const d=draftPreview;if(!d?.items.length)return;if(d.scope==='program'){state.profile.gear=[...d.gear];state.profile.location=d.location;state.draft=null;upsertMemory('equipment','Home equipment',d.gear.join(', '),'dumbbell');persist();navigate('plan');planTab='equipment';render();toast('Equipment settings saved. Active workout and original templates kept.');return}if(state.session){const s=state.session;const done=s.items.map(x=>({...x,sets:x.sets.filter(y=>y.done)})).filter(x=>x.sets.length);for(const x of d.items){if(!available(x.id,d.gear))throw Error('An exercise does not match the approved equipment.');const old=s.items.find(i=>i.exerciseId===x.id),keep=done.find(i=>i.exerciseId===x.id),newSets=old?old.sets.filter(y=>!y.done).slice(0,x.sets):prescribed(x.id,x.sets).sets;if(keep)keep.sets.push(...newSets);else done.push({...prescribed(x.id,0),sourceId:x.sourceId||old?.sourceId||x.id,sets:newSets})}s.items=done;s.currentIndex=Math.max(0,s.items.findIndex(x=>x.sets.some(y=>!y.done)));s.minutes=d.minutes;s.gear=[...d.gear];s.location=d.location;s.warnings=[...d.warnings];s.approvedTotal=totalCount(s);persist();navigate('workout');toast('Unfinished work adjusted. Completed sets kept.')}else{state.draft=clone(d);persist();navigate('today');toast('Today’s version saved. Original program kept.')}}
function chat(text){text=text.trim();if(!text)return;state.chat.push({role:'user',text});let answer='',next=null;if(/\b(pain|hurt|injury|injured|dizzy)\b/i.test(text)){answer='This prototype cannot assess symptoms or recommend training through pain. You can pause or finish early. Use appropriate professional guidance.'}else if(/\b(bodyweight|equipment|dumbbells?|bands?|kettlebells?|hotel|travel)\b|\d+\s*min|shorter|less time/i.test(text)){const m=text.match(/\b(\d{1,2})\s*(?:min|minutes)/i),minutes=m?Math.max(15,Math.min(60,+m[1])):20;let gear=state.session?.gear||state.profile.gear,loc=state.session?.location||state.profile.location;if(/no equipment|bodyweight/i.test(text)){gear=['bodyweight'];loc='Anywhere'}else if(/kettlebell/i.test(text)){gear=['kettlebell'];loc='Home'}else if(/\bbands?\b/i.test(text)){gear=['bands','bodyweight'];loc='Travel'}else if(/dumbbell|hotel/i.test(text)){gear=['dumbbells','bodyweight'];loc=/hotel/i.test(text)?'Hotel':'Home'}next=buildAdjustment(minutes,gear,loc,text);answer='Review this version before applying it. Completed work and your ongoing program stay saved.'}else if(/\b(why|target|progress|weight)\b/i.test(text)){answer=coaching().explanation}else if(/miss|skip|break/i.test(text)){answer='The next session stays in sequence. No automatic catch-up work is added. This prototype does not prescribe return-from-break training.'}else answer='This guided demo can preview time/equipment changes or explain recorded targets. Try “20 minutes, dumbbells only.”';state.chat.push({role:'coach',text:answer});persist();if(next){draftPreview=next;navigate('adapt')}else render()}
document.addEventListener('click',e=>guarded(()=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,index=Number(el.dataset.index);switch(a){case'close-sheet':closeSheet();break;case'profile':settings();break;case'plan-settings':planSettings();break;case'equipment':equipmentSheet();break;case'start':start();break;case'resume':navigate('workout');break;case'exercise':exercise(id);break;case'technique':technique(id);break;case'why':sheet(esc(coaching().title),`<p class="sleeping">${esc(coaching().explanation)}</p><div class="notice mt16">Guided prototype. Targets remain editable; no live AI prescription.</div>`);break;case'library':sheet('Your workout',`<p class="small muted mb16">Tap an exercise for details and technique.</p>${displayedPlan().items.map(x=>exerciseRow(x.id,x.sets)).join('')}`);break;case'adjust':controls();break;case'adjust-controls':controls();break;case'back-adjust':case'cancel-adjust':draftPreview=null;navigate(state.session?'workout':'today');break;case'apply-adjust':applyAdjust();break;case'plan-tab':planTab=el.dataset.tab;render();break;case'progress-tab':progressTab=el.dataset.tab;render();break;case'coach-tab':coachTab=el.dataset.tab;render();break;case'all-history':progressTab='history';render();break;case'go-today':navigate('today');break;case'go-progress':progressTab='history';navigate('progress');break;case'go-coach':navigate('coach');break;case'minimize':navigate('today');break;case'show-memory':coachTab='memory';render();break;case'show-chat':coachTab='chat';render();break;case'keep-plan':toast('Your current plan stays as it is.');break;case'preview-week':navigate('review-plan');break;case'apply-week':state.scheduledTrial={duration:25,startAt:(state.scheduledTrial?new Date(state.scheduledTrial.startAt):nextWeekStart()).toISOString()};persist();navigate('plan');toast('One-week trial scheduled. Today is unchanged.');break;case'cancel-week':state.scheduledTrial=null;persist();navigate('coach');toast('Scheduled trial cancelled.');break;case'preview-plan':{const p=resolvedPlan(index);sheet(p.name,`<p class="small muted mb16">${p.minutes} minutes · ${p.items.length} exercises</p>${p.warnings.map(w=>`<div class="notice amber mt8">${esc(w)}</div>`).join('')}${p.items.map(x=>exerciseRow(x.id,x.sets)).join('')}<button class="primary" data-action="use-plan-session" data-index="${index}" ${!p.items.length?'disabled':''}>Use as next session</button>`);break}case'use-plan-session':state.sequence=index;state.draft=null;persist();navigate('today');toast('Next session selected.');break;case'day':{const i=Number(el.dataset.i);sheet(['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i],`<h3>${({2:[1,4],3:[0,2,4],4:[0,1,3,5]})[state.profile.days].includes(i)?'An intended training day.':'Room for rest.'}</h3><p class="sleeping mt16">Your calendar shows intended days. Your session sequence continues whenever you actually train.</p><button class="primary mt24" data-action="plan-settings">Edit weekly preferences</button>`);break}case'history':showHistory(id);break;case'edit-history':editHistory(id);break;case'edit-memory':if(id==='equipment')equipmentSheet();else if(id==='goal'||id==='duration')planSettings();else editMemory(id);break;case'add-memory':editMemory();break;case'forget-memory':sheet('Forget this preference?',`<p class="sleeping">This removes the saved memory. Your completed workouts stay in history.</p><button class="danger mt24" data-action="confirm-forget" data-id="${esc(id)}">Forget preference</button><button class="secondary mt8" data-action="close-sheet">Keep it</button>`);break;case'confirm-forget':state.memories=state.memories.filter(x=>x.id!==id);persist();closeSheet();render();toast('Preference forgotten');break;case'chat-prompt':chat(el.dataset.text);break;case'log-next':logNext();break;case'toggle-set':{const s=state.session;if(!s||s.pausedAt)break;let set=s.items[s.currentIndex].sets[index];if(!set.done&&loaded(DB[s.items[s.currentIndex].exerciseId])&&set.weight<=0){toast('Enter a starting load before logging.');break}set.done=!set.done;set.completedAt=set.done?Date.now():null;if(set.done)s.restUntil=Date.now()+90000;persist();render();break}case'add-rest':if(state.session){state.session.restUntil=Math.max(state.session.pausedAt||Date.now(),state.session.restUntil||0)+30000;persist();tick()}break;case'skip-rest':if(state.session){state.session.restUntil=state.session.pausedAt||Date.now();persist();tick()}break;case'pause-session':{const s=state.session;if(!s)break;if(s.pausedAt){s.pauseMs+=(Date.now()-s.pausedAt);if(s.restUntil)s.restUntil+=Date.now()-s.pausedAt;s.pausedAt=null}else s.pausedAt=Date.now();persist();render();break}case'next-exercise':if(state.session){state.session.currentIndex=Math.min(state.session.items.length-1,state.session.currentIndex+1);persist();render()}break;case'select-exercise':if(state.session){state.session.currentIndex=index;persist();closeSheet();render()}break;case'session-outline':outline();break;case'swap':swap(index);break;case'apply-swap':sheet('Today or your program?',`<h3>${esc(DB[id].name)}</h3><p class="sleeping mt16">The replacement gets separate history and needs calibration. Completed sets from the original movement stay recorded.</p><button class="primary mt24" data-action="confirm-swap" data-id="${esc(id)}" data-index="${index}" data-permanent="false">Today only</button><button class="secondary mt8" data-action="confirm-swap" data-id="${esc(id)}" data-index="${index}" data-permanent="true">Also change my program</button>`);break;case'confirm-swap':{const s=state.session,old=s.items[index],n=old.sets.filter(x=>!x.done).length,done=old.sets.filter(x=>x.done);if(!n){closeSheet();toast('All sets are already logged. No replacement needed.');break}if(!available(id,s.gear)){toast('Replacement requires equipment unavailable today.');break}let replacement=prescribed(id,n);replacement.sourceId=old.sourceId||state.templates[s.planKey].find(x=>DB[x].pattern===DB[old.exerciseId].pattern)||old.exerciseId;if(!recentEntry(id))replacement.sets.forEach(x=>{x.weight=0});if(el.dataset.permanent==='true'){state.templates[s.planKey]=state.templates[s.planKey].map(x=>x===replacement.sourceId?id:x);replacement.sourceId=id;}if(done.length){old.sets=done;s.items.splice(index+1,0,replacement);s.currentIndex=index+1}else{s.items[index]=replacement;s.currentIndex=index}persist();closeSheet();render();toast('Replacement added. Choose its starting load.');break}case'skip-exercise':{let s=state.session,x=s.items[index];s.skippedCount=(s.skippedCount||0)+x.sets.filter(y=>!y.done).length;x.sets=x.sets.filter(y=>y.done);if(!x.sets.length)s.items.splice(index,1);if(!s.items.length){state.session=null;persist();navigate('today');toast('Session cleared: no completed work.')}else{s.currentIndex=Math.min(index,s.items.length-1);persist();closeSheet();render()}break}case'finish-sheet':finishSheet();break;case'confirm-finish':finish();break;case'discard-session':sheet('Discard this session?',`<p class="sleeping">This discards the active session, including any sets logged in it. Existing workout history is unaffected.</p><button class="danger mt24" data-action="confirm-discard">Discard active session</button><button class="secondary mt8" data-action="close-sheet">Keep training</button>`);break;case'confirm-discard':state.session=null;persist();navigate('today');toast('Active session discarded');break;case'feedback':state.feedback[state.lastFinished]=el.dataset.value;persist();render();toast('Feedback saved');break;case'export':exportData();break;case'restore':$('#restore-file').click();break;case'reset':sheet('Reset the prototype?',`<p class="sleeping">This replaces this prototype’s local data with its initial sample state. Export first if you want to keep your changes.</p><button class="secondary mt16" data-action="export">Export first</button><button class="danger mt8" data-action="confirm-reset">Reset sample data</button>`);break;case'confirm-reset':state=normalizeState(initial());state.revision=baseRevision;persist();navigate('today');toast('Sample state restored');break;case'retry-save':if(persist()){render();toast('Changes saved on this device')}break;}}));
function upsertMemory(id,label,value,ic){const m=state.memories.find(x=>x.id===id);if(m)Object.assign(m,{label,value,icon:ic||m.icon});else state.memories.push({id,label,value,icon:ic||'coach',kind:'confirmed'})}
function editMemory(id){let m=state.memories.find(x=>x.id===id);sheet(m?'Edit a memory':'Add a preference',`<form id="memory-form" data-id="${esc(m?.id||'')}"><div class="field"><label for="memory-label">Preference</label><input id="memory-label" maxlength="60" required value="${esc(m?.label||'')}"></div><div class="field"><label for="memory-value">What should your coach remember?</label><textarea id="memory-value" maxlength="240" required>${esc(m?.value||'')}</textarea></div><p class="small muted">This stores a confirmed preference. Use plan or equipment settings to change workout configuration.</p><button class="primary">Save memory</button></form>${m?`<button class="text-btn muted mt16" data-action="forget-memory" data-id="${esc(m.id)}">${icon('trash')} Forget this preference</button>`:''}`)}
function showHistory(id){const h=state.history.find(x=>x.id===id);if(!h)return;sheet(esc(h.name),`<p class="small muted">${new Date(h.date).toLocaleDateString('en-US',{month:'long',day:'numeric'})} · ${h.minutes} ${h.minutes===1?'minute':'minutes'}${h.sample?' · Sample record':''}${h.partial?' · Finished early':''}</p>${h.entries.map(e=>`<h4 class="mt24">${esc(DB[e.id].name)}</h4>${historySets(e).map((x,i)=>`<div class="history-detail-set"><span>Set ${i+1}</span><strong>${loaded(DB[e.id])?toDisplay(x.weight)+' '+state.profile.units+' × ':''}${x.reps} ${DB[e.id].timed?'sec':'reps'}</strong></div>`).join('')}`).join('')}<button class="secondary mt24" data-action="edit-history" data-id="${esc(h.id)}">${icon('edit')} Correct recorded sets</button><p class="small muted mt16">Corrections update each recorded set. Original session prescriptions remain separate.</p>`)}
function editHistory(id){const h=state.history.find(x=>x.id===id);sheet('Correct workout record',`<form id="history-form" data-id="${esc(id)}">${h.entries.map((e,i)=>`<h4 class="mt24">${esc(DB[e.id].name)}</h4>${historySets(e).map((x,j)=>`<div class="history-edit-row"><span>Set ${j+1}</span>${loaded(DB[e.id])?`<label>${state.profile.units}<input name="history-weight-${i}-${j}" type="number" min="0.01" max="${state.profile.units==='kg'?1000:toDisplay(1000)}" step="any" value="${toDisplay(x.weight)}" required></label>`:''}<label>${DB[e.id].timed?'Seconds':'Reps'}<input name="history-reps-${i}-${j}" type="number" min="1" max="999" step="1" value="${x.reps}" required></label></div>`).join('')}`).join('')}<button class="primary mt24">Save correction</button></form>`)}
document.addEventListener('input',e=>{if(e.target.id==='adjust-mins')$('#mins-output').textContent=e.target.value+' min'});
document.addEventListener('change',e=>{const target=e.target,field=target.dataset.setField,value=target.value,setIndex=Number(target.dataset.set);return guarded(()=>{if(target.id==='progress-exercise'){selectedProgress=value;render()}if(field){const s=state.session;if(!s||!['weight','reps'].includes(field))return;const set=s.items[s.currentIndex].sets[setIndex];if(!set)return;const n=Number(value),canonical=field==='weight'?(n===toDisplay(set.weight)?set.weight:fromDisplay(n)):n;if(value.trim()===''||!Number.isFinite(n)||(field==='reps'&&(!Number.isInteger(n)||n<1||n>999))||(field==='weight'&&(!Number.isFinite(canonical)||canonical<0||canonical>1000||(set.done&&canonical<=0)))){toast(field==='reps'?'Enter whole reps or seconds from 1 to 999.':'Enter a load within the supported range.');render();return}set[field]=canonical;persist()}})});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target;return guarded(()=>{if(f.id==='profile-form'){state.profile.name=f.querySelector('#profile-name').value.trim()||'Krishna';state.profile.units=f.querySelector('#profile-units').value;persist();closeSheet();render();toast('Settings saved')}else if(f.id==='plan-form'){state.profile.goal=f.querySelector('#plan-goal').value;state.profile.days=Number(f.querySelector('#plan-days').value);state.profile.duration=Number(f.querySelector('#plan-duration').value);state.draft=null;upsertMemory('goal','Training goal',state.profile.goal,'goal');upsertMemory('duration','Session preference',state.profile.duration+' minutes','clock');persist();closeSheet();render();toast('Training preferences saved')}else if(f.id==='equipment-form'){const g=[...f.querySelectorAll('input[name=gear]:checked')].map(x=>x.value),loc=f.querySelector('#equip-location').value;draftPreview=buildAdjustment(durationAt(),g,loc,undefined,'program');closeSheet();navigate('adapt')}else if(f.id==='adjust-form'){const minutes=Number(f.querySelector('#adjust-mins').value),choice=f.querySelector('#adjust-location').value,scope=f.dataset.scope||'today',prior=route==='adapt'?draftPreview:(!state.session?state.draft:null),gears={preview:prior?.gear||state.session?.gear||state.profile.gear,current:state.session?.gear||state.profile.gear,dumbbells:['dumbbells','bodyweight'],bodyweight:['bodyweight'],bands:['bands','bodyweight'],kettlebell:['kettlebell']};draftPreview=buildAdjustment(minutes,gears[choice],choice==='preview'?(prior?.location||state.session?.location||state.profile.location):choice==='bodyweight'?'Anywhere':'Home',undefined,scope);closeSheet();navigate('adapt')}else if(f.id==='memory-form'){upsertMemory(f.dataset.id||uid(),f.querySelector('#memory-label').value.trim(),f.querySelector('#memory-value').value.trim(),'coach');persist();closeSheet();render();toast('Memory saved')}else if(f.id==='chat-form'){const text=f.querySelector('#chat-input').value;chat(text)}else if(f.id==='history-form'){const h=state.history.find(x=>x.id===f.dataset.id);const edits=h.entries.map((e,i)=>historySets(e).map((x,j)=>{const w=f.querySelector(`[name="history-weight-${i}-${j}"]`);return {reps:Number(f.querySelector(`[name="history-reps-${i}-${j}"]`).value),weight:w?(Number(w.value)===toDisplay(x.weight)?x.weight:fromDisplay(Number(w.value))):0}}));const updated=correction(h,edits);state.history[state.history.indexOf(h)]=updated;persist();closeSheet();render();toast('Recorded sets corrected.')}});});

$('#restore-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>5000000)throw Error('File is too large.');const obj=JSON.parse(await file.text());if(obj.format!=='strength-coach-export'||obj.version!==1)throw Error('Not a compatible export.');const restored=normalizeState(obj.data);sheet('Restore this export?',`<p class="sleeping">${restored.history.length} records. This replaces current prototype data, including any active session. Export your existing data first if needed.</p><button class="secondary mt16" data-action="export">Export existing data</button><button class="primary mt8" id="confirm-restore">Replace with this export</button><button class="text-btn muted" data-action="close-sheet">Cancel</button>`);$('#confirm-restore').onclick=()=>guarded(()=>{state=clone(restored);state.revision=baseRevision;persist();navigate('today');toast('Export restored. No duplicate records.');})}catch(err){toast('Restore rejected: '+err.message)}});

window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{const newer=normalizeState(JSON.parse(e.newValue));if(newer.revision>baseRevision){state=newer;baseRevision=newer.revision;lastSaved=clone(newer);closeSheet();render();toast('Latest saved state loaded from another tab.')}}catch{toast('Another tab sent invalid data; current state was kept.')}});

render();
